"use strict";

const $ = (selector) => document.querySelector(selector);
const escapeHTML = (value) => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money = value => new Intl.NumberFormat("en-SG", {style:"currency",currency:"SGD"}).format(Number(value) || 0);
const number = value => new Intl.NumberFormat("en-SG", {maximumFractionDigits:3}).format(Number(value) || 0);
const dateText = value => { const d = new Date(value); return Number.isNaN(d.getTime()) ? String(value ?? "—") : d.toLocaleString("en-SG", {dateStyle:"medium",timeStyle:"short"}); };
const key = () => globalThis.crypto?.randomUUID?.() || `request-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const state = {token:sessionStorage.getItem("hf_token"),user:null,view:"orders",branches:[],customers:[],menu:[],ingredients:[],availability:[],stock:[],recipes:{},branch:1,customer:1,cart:[],receipt:null,orderAttempt:null,receiveAttempt:null,discardAttempts:{},editingReview:null,editingMenu:null};
try { state.user = JSON.parse(sessionStorage.getItem("hf_user") || "null"); } catch { sessionStorage.clear(); state.token=null; }
let toastTimer;

async function api(path, options={}) {
  const response = await fetch(`/api${path}`, { ...options, headers:{"Content-Type":"application/json", ...(state.token ? {Authorization:`Bearer ${state.token}`} : {}), ...options.headers}});
  const raw = await response.text();
  let data; try { data = raw ? JSON.parse(raw) : null; } catch { data = null; }
  if (!response.ok) {
    const detail = data?.detail;
    const message = typeof detail === "string" ? detail : detail ? JSON.stringify(detail) : `Request failed (${response.status}). Please try again.`;
    if (response.status === 401 && state.user) { signOut(); $("#login-error").textContent="Your session expired. Please sign in again."; }
    const error = new Error(message); error.status=response.status; throw error;
  }
  return data;
}
const send = (path,method,body) => api(path,{method,body:JSON.stringify(body)});
function toast(message) { $("#toast").textContent=message; $("#toast").hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(()=>$("#toast").hidden=true,5000); }
function showError(error) { $("#page-error").textContent=error.message || String(error); $("#page-error").hidden=false; }
async function action(button, fn) { button.disabled=true; const old=button.textContent; button.textContent="Working…"; $("#page-error").hidden=true; try { await fn(); } catch(error) { showError(error); } finally { if(button.isConnected) { button.disabled=false; button.textContent=old; } } }
function signOut() { state.token=null;state.user=null;state.cart=[];state.receipt=null;state.orderAttempt=null;sessionStorage.removeItem("hf_token");sessionStorage.removeItem("hf_user");$("#workspace").hidden=true;$("#login-screen").hidden=false;$("#login-password").value=""; }
const isManager = () => state.user?.role === "manager";
const isCustomer = () => state.user?.role === "customer";
const options = (rows, selected, label="name", value="id") => rows.map(row=>`<option value="${escapeHTML(row[value])}" ${String(row[value])===String(selected)?"selected":""}>${escapeHTML(row[label])}</option>`).join("");
const empty = text => `<div class="empty">${escapeHTML(text)}</div>`;
const table = (head, rows) => `<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${escapeHTML(h)}</th>`).join("")}</tr></thead><tbody>${rows.join("")}</tbody></table></div>`;
function branchControl(all=false) { return `<label>Branch<select id="branch-selector" ${state.user.role==="cashier"?"disabled":""}>${all?'<option value="">All branches</option>':""}${options(state.branches,state.branch)}</select></label>`; }
function customerControl(id="customer-selector") { return `<label>Customer<select id="${id}">${options(state.customers,state.customer)}</select></label>`; }
function wireBranch(callback=renderView) { $("#branch-selector")?.addEventListener("change",event=>{state.branch=event.target.value ? Number(event.target.value) : "";callback();}); }
function freshAttempt(existing,payload) { const fingerprint=JSON.stringify(payload);return existing?.fingerprint===fingerprint ? existing : {fingerprint,request_key:key()}; }

$("#demo-hint").textContent="Development accounts only. Password for each role: DemoPass123!";
document.querySelectorAll("[data-demo]").forEach(button=>button.addEventListener("click",()=>{ const role=button.dataset.demo;$("#login-email").value=`${role==="customer"?"customer1":role}@hawkerflow.local`;$("#login-password").value="DemoPass123!";$("#login-email").focus(); }));
$("#login-form").addEventListener("submit",async event=>{
  event.preventDefault();const button=event.submitter;button.disabled=true;$("#login-error").textContent="";
  try { const result=await send("/auth/login","POST",{email:$("#login-email").value,password:$("#login-password").value});state.token=result.access_token;state.user=result.user;sessionStorage.setItem("hf_token",state.token);sessionStorage.setItem("hf_user",JSON.stringify(state.user));await openWorkspace(); }
  catch(error) { $("#login-error").textContent=error.message; }
  finally {button.disabled=false;}
});
$("#logout").addEventListener("click",signOut);
document.querySelectorAll("[data-view]").forEach(button=>button.addEventListener("click",()=>{state.view=button.dataset.view;renderView();}));
async function openWorkspace() {
  const [branches,menu,customers] = await Promise.all([api("/branches"),api("/menu"),isCustomer()?Promise.resolve([{id:state.user.customer_id,name:state.user.name}]):api("/customers")]);
  state.branches=branches;state.menu=menu;state.customers=customers;state.branch=state.user.branch_id || branches[0]?.id || 1;state.customer=state.user.customer_id || customers[0]?.id || 1;
  $("#user-name").textContent=state.user.name;$("#user-role").textContent=state.user.role;$("#user-avatar").textContent=state.user.name.slice(0,1).toUpperCase();
  document.querySelector('[data-view="dashboard"]').hidden=!isManager();document.querySelector('[data-view="inventory"]').hidden=isCustomer();
  $("#login-screen").hidden=true;$("#workspace").hidden=false;$("#today-label").textContent=new Date().toLocaleDateString("en-SG",{timeZone:"Asia/Singapore",weekday:"short",day:"numeric",month:"short",year:"numeric"});
  state.view="orders";await renderView();
}
const viewCopy={orders:["COUNTER & LOYALTY","Orders & points","A smooth checkout. Stock and loyalty updated together."],inventory:["KITCHEN OPERATIONS","Kitchen stock","Know what is available and receive new ingredients."],feedback:["CUSTOMER COMMUNITY","Customers & feedback","Every visit is a chance to listen and improve."],dashboard:["MANAGER WORKSPACE","Manager intelligence","Forecast stock, reduce waste and understand sales and customer loyalty."]};
let renderVersion=0;
async function renderView() {
  const version=++renderVersion;$("#page-error").hidden=true;const copy=viewCopy[state.view];$("#view-eyebrow").textContent=copy[0];$("#view-title").textContent=copy[1];$("#view-description").textContent=copy[2];document.querySelectorAll("[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===state.view));
  $("#content").innerHTML='<div class="loading">Loading your workspace…</div>';
  try {await ({orders:renderOrders,inventory:renderInventory,feedback:renderFeedback,dashboard:renderDashboard}[state.view])(version);} catch(error) {if(version===renderVersion){$("#content").innerHTML='<div class="card empty">This view could not load. Use the navigation to try again.</div>';showError(error);}}
}
async function renderOrders(version) {
  if(!state.branch)state.branch=state.user.branch_id || state.branches[0]?.id;
  const query=isCustomer()?`customer_id=${state.user.customer_id}`:`branch_id=${state.branch}`;
  const [orders,loyalty,menu,ingredients,availability,stock]=await Promise.all([api(`/orders?${query}`),api(`/loyalty/${state.customer}`),api(isManager()?"/menu?include_inactive=true":"/menu"),isManager()?api("/ingredients"):Promise.resolve([]),isCustomer()?Promise.resolve([]):api(`/menu/availability?branch_id=${state.branch}`),isCustomer()?Promise.resolve([]):api(`/inventory?branch_id=${state.branch}`)]);
  const recipes=isCustomer()?{}:Object.fromEntries(await Promise.all(menu.filter(item=>item.is_active!==false).map(async item=>{const components=availability.find(row=>row.menu_item_id===item.id)?.recipe_ingredients;return [item.id,components?components.map(c=>({ingredient_id:c.ingredient_id,quantity:c.required_per_portion})):await api(`/menu/${item.id}/recipe`)];})));
  if(version!==renderVersion)return;state.menu=menu;state.ingredients=ingredients;state.availability=availability;state.stock=stock;state.recipes=recipes;
  const filters=isCustomer()?"":`<div class="card filter-card"><div class="form-row">${branchControl()}${customerControl()}<div class="hint">Points balance: <b>${escapeHTML(loyalty.balance)}</b><br>100 points = ${money(1)}</div></div><details style="margin-top:12px"><summary class="text-button">Register a customer</summary><form id="customer-form" class="form-row" style="margin-top:12px"><label>Name<input name="name" required maxlength="150"></label><label>Email<input name="email" type="email" required maxlength="254"></label><button class="button secondary" type="submit">Register customer</button></form><p class="hint">Creates a purchase and loyalty record. Customer sign-in accounts are provisioned separately.</p></details></div>`;
  $("#content").innerHTML=filters+(state.receipt?receiptHTML(state.receipt):"")+(!isCustomer()?`<div class="two-column"><section class="card"><div class="card-head"><div><h3>Build an order</h3><p class="muted">Select a dish to add it to the bill.</p></div><span class="pill neutral">Cash sale</span></div><div class="menu-grid">${menu.filter(m=>m.is_active!==false).map(m=>`<button class="menu-item" data-add="${escapeHTML(m.id)}"><div><b>${escapeHTML(m.name)}</b><small>${escapeHTML(m.category)}</small></div><span class="menu-price">${money(m.price)} +</span></button>`).join("") || empty("No active menu items. Ask your manager to add dishes.")}</div>${isManager()?menuFormHTML():""}</section><section class="card"><div class="card-head"><h3>Current bill</h3><span id="cart-count" class="pill neutral"></span></div><div id="cart"></div><label>Redeem points<input id="redeem-points" type="number" min="0" step="100" value="0"></label><p class="hint">Use multiples of 100. Your preview is estimated; the server checks prices, stock and points.</p><div id="cart-totals"></div><button id="checkout" class="button primary full">Complete cash order →</button><p class="hint" style="margin-top:12px">A failed request keeps its request key so retrying the same bill is safe.</p></section></div>`:"" )+`<section class="card"><div class="card-head"><div><h3>${isCustomer()?"Your orders":"Recent orders"}</h3><p class="muted">${isCustomer()?"Your purchase history and earned points.":"Completed orders for the selected branch."}</p></div><span class="pill neutral">${orders.length} orders</span></div>${orders.length?table(["Order","Placed","Customer","Status","Total","Receipt"],orders.map(order=>`<tr><td>#${escapeHTML(order.id)}</td><td>${escapeHTML(dateText(order.created_at))}</td><td>${escapeHTML(state.customers.find(c=>c.id===order.customer_id)?.name || `Customer ${order.customer_id}`)}</td><td><span class="pill">${escapeHTML(order.status)}</span></td><td>${money(order.total)}</td><td><button class="text-button" data-receipt="${escapeHTML(order.id)}">View →</button></td></tr>`)):empty("No orders yet.")}</section><section class="card"><div class="card-head"><div><h3>Points ledger</h3><p class="muted">Customer: ${escapeHTML(state.customers.find(c=>c.id===state.customer)?.name || state.user.name)}</p></div><span class="pill">${escapeHTML(loyalty.balance)} points</span></div>${loyalty.transactions?.length?table(["Event","Order","Points","Recorded"],loyalty.transactions.map(t=>`<tr><td>${escapeHTML(t.event_type)}</td><td>${t.order_id==null?"—":`#${escapeHTML(t.order_id)}`}</td><td>${Number(t.points_delta)>0?"+":""}${escapeHTML(t.points_delta)}</td><td>${escapeHTML(dateText(t.created_at))}</td></tr>`)):empty("No point transactions yet.")}</section>`;
  wireBranch();$("#customer-selector")?.addEventListener("change",e=>{state.customer=Number(e.target.value);renderView();});
  document.querySelectorAll("[data-add]").forEach(button=>{
    const id=Number(button.dataset.add),stock=availability.find(row=>row.menu_item_id===id);
    button.disabled=!stock?.sellable;button.title=stock?.sellable?`${stock.available_portions} portions currently available`:"Unavailable: insufficient usable ingredients or recipe missing";
    const label=document.createElement("small");label.className="stock-availability";label.textContent=stock?.sellable?`${stock.available_portions} portions available`:"Currently unavailable";button.querySelector("div").append(label);
    button.addEventListener("click",()=>{const line=state.cart.find(x=>x.menu_item_id===id);if(!canAddPortion(id))return;if(line)line.quantity++;else state.cart.push({menu_item_id:id,quantity:1,notes:""});renderCart();});
  });
  $("#redeem-points")?.addEventListener("input",renderTotals);$("#checkout")?.addEventListener("click",event=>action(event.currentTarget,checkout));renderCart();
  document.querySelectorAll("[data-receipt]").forEach(b=>b.addEventListener("click",()=>action(b,async()=>{state.receipt=await api(`/orders/${b.dataset.receipt}`);await renderView();window.scrollTo({top:0,behavior:"smooth"});})));
  $("#customer-form")?.addEventListener("submit",event=>{event.preventDefault();const f=event.target;action(event.submitter,async()=>{const customer=await send("/customers","POST",{name:f.elements.name.value,email:f.elements.email.value});state.customers=await api("/customers");state.customer=customer.id;toast("Customer registered.");await renderView();});});
  $("#close-receipt")?.addEventListener("click",()=>{state.receipt=null;$(".receipt")?.remove();});wireMenuForm();
}
function receiptHTML(order) {
  return `<section class="receipt"><div class="card-head"><div><span class="eyebrow teal">ORDER RECEIPT</span><h3 style="margin-top:9px">Order #${escapeHTML(order.id)} · ${escapeHTML(order.status)}</h3></div><button id="close-receipt" class="text-button">Close</button></div><div class="receipt-grid"><div>Total<strong>${money(order.total)}</strong></div><div>Points redeemed<strong>${escapeHTML(order.points_redeemed ?? 0)}</strong></div>${order.points_earned!=null?`<div>Points earned<strong>${escapeHTML(order.points_earned)}</strong></div>`:""}${order.loyalty_balance!=null?`<div>Current points balance<strong>${escapeHTML(order.loyalty_balance)} points</strong></div>`:""}</div>${order.lines?.length?table(["Dish","Quantity","Unit price","Notes"],order.lines.map(line=>`<tr><td>${escapeHTML(line.name || line.menu_item_name || state.menu.find(m=>m.id===line.menu_item_id)?.name || line.menu_item_id)}</td><td>${escapeHTML(line.quantity)}</td><td>${money(line.unit_price)}</td><td>${escapeHTML(line.notes)}</td></tr>`)):""}<p class="hint">${escapeHTML(dateText(order.created_at))}</p></section>`;
}
function renderCart() {
  if(!$("#cart"))return;$("#cart-count").textContent=`${state.cart.reduce((n,l)=>n+l.quantity,0)} items`;
  $("#cart").innerHTML=state.cart.length?state.cart.map(line=>`<div class="cart-line"><div class="cart-top"><b>${escapeHTML(state.menu.find(m=>m.id===line.menu_item_id)?.name || "Dish")}</b><div class="quantity-control"><button data-quantity="${line.menu_item_id}" data-delta="-1" aria-label="Remove one">−</button><span>${line.quantity}</span><button data-quantity="${line.menu_item_id}" data-delta="1" aria-label="Add one">+</button></div></div><input class="notes" data-notes="${line.menu_item_id}" value="${escapeHTML(line.notes)}" placeholder="Optional note, e.g. no chilli" maxlength="500"></div>`).join(""):empty("Your bill is empty. Select a dish to get started.");
  $("#cart").querySelectorAll("[data-quantity]").forEach(b=>b.addEventListener("click",()=>{const id=Number(b.dataset.quantity),delta=Number(b.dataset.delta);if(delta>0&&!canAddPortion(id))return;const line=state.cart.find(l=>l.menu_item_id===id);line.quantity+=delta;state.cart=state.cart.filter(l=>l.quantity>0);renderCart();}));
  $("#cart").querySelectorAll("[data-notes]").forEach(input=>input.addEventListener("input",()=>{state.cart.find(l=>l.menu_item_id===Number(input.dataset.notes)).notes=input.value;}));renderTotals();
}
function renderTotals() {
  if(!$("#cart-totals"))return;const subtotal=state.cart.reduce((n,l)=>n+Number(state.menu.find(m=>m.id===l.menu_item_id)?.price || 0)*l.quantity,0);const redeemed=Number($("#redeem-points").value)||0;
  $("#cart-totals").innerHTML=`<div class="cart-totals"><div class="total-row"><span>Estimated subtotal</span><b>${money(subtotal)}</b></div><div class="total-row"><span>Points discount</span><b>− ${money(redeemed/100)}</b></div><div class="total-row large"><span>Estimated total</span><span>${money(subtotal-redeemed/100)}</span></div></div>`;const stockIssue=cartStockIssue();$("#checkout").disabled=!state.cart.length || Boolean(stockIssue);if(stockIssue)$("#cart-totals").insertAdjacentHTML("beforeend",`<p class="form-error" role="alert">${escapeHTML(stockIssue)}</p>`);
}
async function checkout() {
  if(!state.cart.length)throw new Error("Add at least one dish first.");const stockIssue=cartStockIssue();if(stockIssue)throw new Error(stockIssue);const payload={branch_id:Number(state.branch),customer_id:state.customer,redeem_points:Number($("#redeem-points").value),lines:state.cart.map(l=>({...l}))};state.orderAttempt=freshAttempt(state.orderAttempt,payload);
  const order=await send("/orders","POST",{...payload,request_key:state.orderAttempt.request_key});state.receipt=order;state.cart=[];state.orderAttempt=null;toast(`Order #${order.id} completed.`);await renderView();
}
function canAddPortion(id) {
  const availability=state.availability.find(item=>item.menu_item_id===id),quantity=state.cart.find(item=>item.menu_item_id===id)?.quantity || 0;
  if(!availability?.sellable || quantity>=Number(availability.available_portions)){toast("This dish has reached its currently available portions. Stock is checked again at checkout.");return false;}
  const candidate=state.cart.map(line=>({...line})),line=candidate.find(item=>item.menu_item_id===id);if(line)line.quantity++;else candidate.push({menu_item_id:id,quantity:1});
  const issue=cartStockIssue(candidate);if(issue){toast(issue);return false;}return true;
}
function cartStockIssue(lines=state.cart) {
  const required=new Map();
  for(const line of lines){
    const availability=state.availability.find(item=>item.menu_item_id===line.menu_item_id);
    if(!availability?.sellable || line.quantity>Number(availability.available_portions))return "A dish in this bill exceeds its currently available portions. Reduce its quantity or refresh stock.";
    const recipe=state.recipes[line.menu_item_id] || [];if(!recipe.length)return "A dish in this bill has no configured recipe.";
    for(const component of recipe)required.set(component.ingredient_id,(required.get(component.ingredient_id)||0)+Math.round(Number(component.quantity)*10000)*line.quantity);
  }
  for(const [ingredient,quantity] of required){const stock=state.stock.find(row=>row.ingredient_id===ingredient),usable=Math.round(Number(stock?.sellable_quantity ?? stock?.quantity ?? 0)*10000);if(quantity>usable)return `This bill exceeds the usable ${stock?.name || "ingredient"} stock shared by its dishes. Reduce quantities; stock is checked again at checkout.`;}
  return null;
}
function menuFormHTML() {
  return `<details class="manager-form"><summary class="text-button">Manage the menu</summary><p class="hint">Change future sale prices or deactivate dishes. Historical receipts keep their paid prices.</p><div class="table-wrap">${table(["Dish","Price","Actions"],state.menu.map(m=>`<tr><td>${escapeHTML(m.name)}</td><td>${money(m.price)} ${m.is_active?"":"· inactive"}</td><td class="row-actions"><button class="text-button" data-menu-edit="${escapeHTML(m.id)}">Edit</button> · <button class="text-button" data-menu-toggle="${escapeHTML(m.id)}">${m.is_active?"Deactivate":"Reactivate"}</button></td></tr>`))}</div><form id="menu-form"><h3 id="menu-form-title">Add a dish</h3><div class="form-row"><label>Name<input name="name" required maxlength="120"></label><label>Category<input name="category" required maxlength="80"></label><label>Price<input name="price" type="number" min="0.01" step="0.01" required></label></div><button class="button secondary" type="submit">Save dish</button><button type="button" id="menu-reset" class="text-button">Cancel editing</button><p class="hint">Define its recipe below before selling a new dish.</p></form><form id="recipe-form" class="manager-form"><h3>Recipe quantities</h3><label>Dish<select id="recipe-dish" name="menu_item_id">${options(state.menu,state.menu[0]?.id)}</select></label><p class="hint">Enter the amount of each ingredient needed for one serving. Leave unused ingredients at zero. Saving replaces the dish’s recipe.</p><div id="recipe-ingredients" class="loading">Loading recipe…</div><button class="button secondary" type="submit">Save recipe</button></form></details>`;
}
function wireMenuForm() {
  const form=$("#menu-form");if(!form)return;state.editingMenu=null;
  $("#menu-reset").addEventListener("click",()=>{state.editingMenu=null;form.reset();$("#menu-form-title").textContent="Add a dish";});
  document.querySelectorAll("[data-menu-edit]").forEach(b=>b.addEventListener("click",()=>{const m=state.menu.find(m=>m.id===Number(b.dataset.menuEdit));state.editingMenu=m.id;form.elements.name.value=m.name;form.elements.category.value=m.category;form.elements.price.value=m.price;$("#menu-form-title").textContent=`Edit ${m.name}`;form.scrollIntoView({behavior:"smooth",block:"center"});}));
  document.querySelectorAll("[data-menu-toggle]").forEach(b=>b.addEventListener("click",()=>action(b,async()=>{const m=state.menu.find(item=>item.id===Number(b.dataset.menuToggle));if(m.is_active)await api(`/menu/${m.id}`,{method:"DELETE"});else await send(`/menu/${m.id}`,"PATCH",{is_active:true});toast(m.is_active?"Dish deactivated.":"Dish reactivated.");await renderView();})));
  form.addEventListener("submit",event=>{event.preventDefault();action(event.submitter,async()=>{const body={name:form.elements.name.value,category:form.elements.category.value,price:Number(form.elements.price.value)};await send(state.editingMenu?`/menu/${state.editingMenu}`:"/menu",state.editingMenu?"PATCH":"POST",body);toast("Menu saved.");await renderView();});});  const recipeForm=$("#recipe-form");
  const loadRecipe=async()=>{const id=Number($("#recipe-dish").value);if(!id){$("#recipe-ingredients").innerHTML=empty("Add a dish first.");return;}$("#recipe-ingredients").className="loading";$("#recipe-ingredients").textContent="Loading recipe…";try{const recipe=await api(`/menu/${id}/recipe`);if(!recipeForm.isConnected||Number($("#recipe-dish").value)!==id)return;$("#recipe-ingredients").className="";$("#recipe-ingredients").innerHTML=table(["Ingredient","Unit","Per serving"],state.ingredients.map(ingredient=>`<tr><td>${escapeHTML(ingredient.name)}</td><td>${escapeHTML(ingredient.unit)}</td><td><input aria-label="${escapeHTML(ingredient.name)} per serving" type="number" min="0" step="0.0001" data-recipe-ingredient="${escapeHTML(ingredient.id)}" value="${escapeHTML(recipe.find(c=>c.ingredient_id===ingredient.id)?.quantity||0)}"></td></tr>`));}catch(error){if(recipeForm.isConnected){$("#recipe-ingredients").className="";$("#recipe-ingredients").innerHTML=errorCard(error);}}};
  $("#recipe-dish").addEventListener("change",loadRecipe);loadRecipe();
  recipeForm.addEventListener("submit",event=>{event.preventDefault();action(event.submitter,async()=>{const components=[...recipeForm.querySelectorAll("[data-recipe-ingredient]")].map(input=>({ingredient_id:Number(input.dataset.recipeIngredient),quantity:Number(input.value)})).filter(c=>c.quantity>0);if(!components.length)throw new Error("Add at least one ingredient quantity.");await send(`/menu/${Number($("#recipe-dish").value)}/recipe`,"PUT",components);toast("Recipe saved.");await renderView();});});
}

async function renderInventory(version) {
  if(!state.branch)state.branch=state.user.branch_id || state.branches[0]?.id;
  const [rows,ingredients,batches]=await Promise.all([api(`/inventory?branch_id=${state.branch}`),isManager()?api("/ingredients"):Promise.resolve([]),api(`/inventory/batches?branch_id=${state.branch}`)]);if(version!==renderVersion)return;state.ingredients=ingredients;
  const low=rows.filter(r=>Number(r.sellable_quantity ?? r.quantity)<=Number(r.reorder_level)).length;
  $("#content").innerHTML=`<div class="card filter-card"><div class="form-row">${branchControl()}<p class="hint">Ingredient quantities and unit costs use the stock unit shown for each ingredient. Reorder status uses usable stock, excluding expired batches.</p></div></div><div class="metrics"><div class="metric"><span>Stocked ingredients</span><strong>${rows.length}</strong><small>At the selected branch</small></div><div class="metric"><span>At or below reorder level</span><strong>${low}</strong><small>Plan the next delivery</small></div><div class="metric"><span>Stock operations</span><strong>${isManager()?"Receive":"View"}</strong><small>${isManager()?"Every receipt is audited":"Manager receives deliveries"}</small></div></div><div class="${isManager()?"two-column":""}"><section class="card"><div class="card-head"><div><h3>Ingredient stock</h3><p class="muted">Quantities update when an order is completed.</p></div><span class="pill neutral">Live inventory</span></div>${rows.length?table(["Ingredient","On hand / usable / expired","Reorder level","Status"],rows.map(r=>`<tr><td><b>${escapeHTML(r.name)}</b></td><td>${number(r.quantity)} ${escapeHTML(r.unit)} total<br><b>${number(r.sellable_quantity ?? r.quantity)} usable</b><br><small>${number(r.expired_quantity)} expired</small></td><td>${isManager()?`<div class="inline-actions"><input data-reorder="${escapeHTML(r.ingredient_id)}" aria-label="${escapeHTML(r.name)} reorder level" type="number" min="0" step="0.0001" value="${escapeHTML(r.reorder_level)}" style="width:90px;padding:7px;margin:0"><button data-reorder-save="${escapeHTML(r.ingredient_id)}" class="text-button">Save</button></div>`:`${number(r.reorder_level)} ${escapeHTML(r.unit)}`}</td><td><span class="pill ${Number(r.sellable_quantity ?? r.quantity)<=Number(r.reorder_level)?"warning":""}">${Number(r.sellable_quantity ?? r.quantity)<=Number(r.reorder_level)?"Reorder":"Available"}</span></td></tr>`)):empty("No stock configured for this branch.")}</section>${isManager()?`<section class="card"><div class="card-head"><div><h3>Receive ingredients</h3><p class="muted">Record a delivery into this branch.</p></div></div><form id="receive-form"><label>Ingredient<select name="ingredient_id" required>${options(ingredients.map(item=>({...item,name:`${item.name} (${item.unit})`})),ingredients[0]?.id)}</select></label><label>Quantity received<input name="quantity" type="number" min="0.0001" step="0.0001" required placeholder="Enter quantity in the stock unit"></label><button class="button primary full" type="submit">Record stock receipt →</button><p class="hint">Repeated retries of the same receipt reuse its request key.</p></form><details class="manager-form"><summary class="text-button">Add an ingredient</summary><form id="ingredient-form" style="margin-top:14px"><label>Ingredient name<input name="name" required maxlength="150"></label><label>Stock unit<input name="unit" required maxlength="20" placeholder="kg, litre, piece"></label><p class="hint">Recipe quantities and received quantities use this same unit.</p><button class="button secondary full" type="submit">Add ingredient</button></form></details></section>`:""}</div>`;
  $("#receive-form")?.querySelector('button[type="submit"]').insertAdjacentHTML("beforebegin",`<div class="form-row"><label>Expiry date (optional)<input name="expires_on" type="date"></label><label>Cost per stock unit (optional)<input name="unit_cost" type="number" min="0" step="0.0001" placeholder="SGD per ingredient stock unit (g/ml/each)"></label></div><p class="hint">Each delivery becomes a batch. Past-date stock is recorded but cannot be sold. Without an expiry date, expiry risk is unknown; without cost, its value is unknown.</p>`);
  $("#content").insertAdjacentHTML("beforeend",`<section class="card"><div class="card-head"><div><h3>Stock batches & expiry</h3><p class="muted">Dated stock uses earliest expiry first. Unknown expiry is labelled explicitly; verify actual expiry before using that stock.</p></div></div>${batchesHTML(batches,true)}</section>`);
  wireDiscardBatches();
  document.querySelectorAll("[data-reorder-save]").forEach(button=>button.addEventListener("click",()=>action(button,async()=>{const ingredient=Number(button.dataset.reorderSave),input=document.querySelector(`[data-reorder="${ingredient}"]`);if(!input.checkValidity())throw new Error("Enter a non-negative reorder level with at most four decimal places.");await send(`/inventory/${state.branch}/${ingredient}`,"PATCH",{reorder_level:Number(input.value)});toast("Reorder level saved.");await renderView();})));
  $("#ingredient-form")?.addEventListener("submit",event=>{event.preventDefault();const form=event.target;action(event.submitter,async()=>{await send("/ingredients","POST",{name:form.elements.name.value,unit:form.elements.unit.value});toast("Ingredient added. Receive its first delivery to stock it.");await renderView();});});
  wireBranch();$("#receive-form")?.addEventListener("submit",event=>{event.preventDefault();const form=event.target;action(event.submitter,async()=>{const payload={branch_id:Number(state.branch),ingredient_id:Number(form.elements.ingredient_id.value),quantity:Number(form.elements.quantity.value),expires_on:form.elements.expires_on.value || null,unit_cost:form.elements.unit_cost.value===""?null:Number(form.elements.unit_cost.value)};state.receiveAttempt=freshAttempt(state.receiveAttempt,payload);await send("/inventory/receive","POST",{...payload,request_key:state.receiveAttempt.request_key});state.receiveAttempt=null;toast("Stock receipt recorded.");await renderView();});});
}

async function renderFeedback(version) {
  if(!state.branch)state.branch=state.user.branch_id || state.branches[0]?.id;
  const [reviews,orders,profile,loyalty]=await Promise.all([api(`/reviews?branch_id=${state.branch}&limit=100`),api(isCustomer()?`/orders?customer_id=${state.user.customer_id}`:`/orders?branch_id=${state.branch}`),isCustomer()||isManager()?api(`/profiles/${state.customer}`).catch(error=>{if(error.status===404)return {};throw error;}):Promise.resolve(null),isCustomer()||isManager()?api(`/loyalty/${state.customer}`):Promise.resolve(null)]);if(version!==renderVersion)return;
  const eligible=orders.filter(order=>order.status==="completed"&&!reviews.some(review=>Number(review.order_id)===order.id));
  $("#content").innerHTML=`<div class="card filter-card"><div class="form-row">${branchControl()}${isManager()?customerControl("profile-customer"):""}<p class="hint">Reviews are linked to completed orders. Preferences do not store your points balance.</p></div></div><div class="two-column"><section class="card"><div class="card-head"><div><h3>Customer voices</h3><p class="muted">Latest reviews for the selected branch.</p></div><span class="pill neutral">${reviews.length} reviews</span></div>${reviews.length?reviews.map(reviewHTML).join(""):empty("No reviews yet for this branch.")}</section><div>${isCustomer()||isManager()?`<section class="card review-form-card"><div class="card-head"><div><h3 id="review-form-title">Share a visit</h3><p class="muted">One review per completed order.</p></div></div><form id="review-form"><label>Order<select name="order_id" required><option value="">Choose an order</option>${eligible.map(o=>`<option value="${escapeHTML(o.id)}">#${escapeHTML(o.id)} · ${money(o.total)}</option>`).join("")}</select></label><label>Rating<select name="rating">${[5,4,3,2,1].map(r=>`<option value="${r}">${r} / 5</option>`).join("")}</select></label><label>Your review<textarea name="text" maxlength="2000" required placeholder="Tell us about your visit"></textarea></label><label>Tags<input name="tags" maxlength="500" placeholder="fast service, too spicy"></label><p class="hint">Separate tags with commas.</p><div class="form-row"><label>Food rating (optional)<input name="food_rating" type="number" min="1" max="5" step="1"></label><label>Service rating (optional)<input name="service_rating" type="number" min="1" max="5" step="1"></label></div><button class="button primary full" type="submit">Save review →</button><button type="button" id="review-reset" class="text-button">Cancel editing</button></form></section>`:""}${profile!==null?profileHTML(profile,loyalty):`<section class="card"><h3>Customer profiles</h3><p class="muted">Customer preferences can be edited by their owner or a manager.</p></section>`}</div></div>`;
  wireBranch();$("#profile-customer")?.addEventListener("change",event=>{state.customer=Number(event.target.value);renderView();});state.editingReview=null;
  document.querySelectorAll("[data-review-edit]").forEach(b=>b.addEventListener("click",()=>{const review=reviews.find(r=>String(r.id || r._id)===b.dataset.reviewEdit);const f=$("#review-form");state.editingReview=b.dataset.reviewEdit;f.elements.order_id.innerHTML=`<option value="${escapeHTML(review.order_id)}">Order #${escapeHTML(review.order_id)}</option>`;f.elements.order_id.disabled=true;f.elements.rating.value=review.rating;f.elements.text.value=review.text;f.elements.tags.value=(review.tags || []).join(", ");f.elements.food_rating.value=review.category_ratings?.food || "";f.elements.service_rating.value=review.category_ratings?.service || "";$("#review-form-title").textContent="Edit your review";f.scrollIntoView({behavior:"smooth",block:"center"});}));
  document.querySelectorAll("[data-review-delete]").forEach(b=>b.addEventListener("click",()=>{if(!confirm("Delete this review and its replies? This cannot be undone."))return;action(b,async()=>{await api(`/reviews/${encodeURIComponent(b.dataset.reviewDelete)}`,{method:"DELETE"});toast("Review deleted.");await renderView();});}));
  $("#review-reset")?.addEventListener("click",()=>renderView());
  $("#review-form")?.addEventListener("submit",event=>{event.preventDefault();const f=event.target;action(event.submitter,async()=>{const category_ratings={};if(f.elements.food_rating.value)category_ratings.food=Number(f.elements.food_rating.value);if(f.elements.service_rating.value)category_ratings.service=Number(f.elements.service_rating.value);const payload={rating:Number(f.elements.rating.value),text:f.elements.text.value,tags:f.elements.tags.value.split(",").map(x=>x.trim()).filter(Boolean),category_ratings};if(!state.editingReview)payload.order_id=Number(f.elements.order_id.value);await send(state.editingReview?`/reviews/${encodeURIComponent(state.editingReview)}`:"/reviews",state.editingReview?"PATCH":"POST",payload);toast("Review saved.");state.editingReview=null;await renderView();});});
  document.querySelectorAll(".reply-form").forEach(f=>f.addEventListener("submit",event=>{event.preventDefault();action(event.submitter,async()=>{await send(`/reviews/${encodeURIComponent(f.dataset.review)}/replies`,"POST",{text:f.elements.text.value});toast("Manager reply added.");await renderView();});}));
  $("#profile-form")?.addEventListener("submit",event=>{event.preventDefault();const f=event.target;action(event.submitter,async()=>{const communication_preferences={email:f.elements.email.checked,sms:f.elements.sms.checked,push:f.elements.push.checked},milestones=profile.milestones||{};const split=x=>x.split(",").map(v=>v.trim()).filter(Boolean);await send(`/profiles/${state.customer}`,"PUT",{dietary_preferences:split(f.elements.dietary.value),favourite_categories:split(f.elements.favourites.value),communication_preferences,milestones});toast("Customer preferences saved.");await renderView();});});
}
function reviewHTML(review) {
  const id=escapeHTML(review.id || review._id),editable=isManager()||Number(review.customer_id)===state.user.customer_id;
  return `<article class="review"><div class="review-top"><div><b>${escapeHTML(review.customer_name || `Customer ${review.customer_id}`)}</b><div class="hint">Order #${escapeHTML(review.order_id)} · ${escapeHTML(dateText(review.created_at))}</div></div><span class="stars" aria-label="${escapeHTML(review.rating)} out of 5">${"★".repeat(Math.min(5,Math.max(0,Number(review.rating)||0)))}</span></div><p>${escapeHTML(review.text)}</p><div class="tags">${(review.tags||[]).map(t=>`<span class="tag">${escapeHTML(t)}</span>`).join("")}</div>${(review.replies||[]).map(r=>`<div class="reply"><b>MANAGER REPLY</b>${escapeHTML(r.text)}</div>`).join("")}${editable?`<div class="review-actions"><button class="text-button" data-review-edit="${id}">Edit review</button><button class="text-button" style="color:var(--red)" data-review-delete="${id}">Delete</button></div>`:""}${isManager()?`<form class="reply-form" data-review="${id}"><input name="text" required maxlength="1000" placeholder="Add a manager reply" aria-label="Manager reply"><button type="submit" class="button secondary small">Reply</button></form>`:""}</article>`;
}
function profileHTML(profile,loyalty) {
  return `<section class="card"><div class="card-head"><div><h3>Customer preferences</h3><p class="muted">${escapeHTML(state.customers.find(c=>c.id===state.customer)?.name || state.user.name)}</p></div></div><div class="profile-summary"><div><small>Available loyalty points</small><strong>${escapeHTML(loyalty.balance)}</strong></div><small>SQL ledger<br>100 points = ${money(1)}</small></div><form id="profile-form"><label>Dietary preferences<input name="dietary" value="${escapeHTML((profile.dietary_preferences||[]).join(", "))}" placeholder="vegetarian, less sugar"></label><label>Favourite categories<input name="favourites" value="${escapeHTML((profile.favourite_categories||[]).join(", "))}" placeholder="Noodles, Drinks"></label><p class="hint">Separate preferences with commas.</p><p class="section-label">Contact preferences</p><div class="preference-options">${["email","sms","push"].map(channel=>`<label><input name="${channel}" type="checkbox" ${profile.communication_preferences?.[channel]?"checked":""}> ${channel==="sms"?"SMS":channel==="push"?"App notifications":"Email"}</label>`).join("")}</div>${Object.keys(profile.milestones||{}).length?`<p class="section-label">Customer milestones</p><div class="tags" style="margin-bottom:18px">${Object.entries(profile.milestones).map(([name,label])=>`<span class="tag">${escapeHTML(name)} · ${escapeHTML(label)}</span>`).join("")}</div>`:""}<button class="button secondary full" type="submit">Save preferences</button></form></section>`;
}

function isoDay(date) { return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`; }
function singaporeToday() {return new Date(`${new Intl.DateTimeFormat("en-CA",{timeZone:"Asia/Singapore",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date())}T12:00:00`);}
let dashboardDates=null;
function errorCard(error) {return `<div class="form-error">${escapeHTML(error?.message || "The database query could not complete.")}</div>`;}
function genericTable(rows) {if(!rows.length)return empty("No matching data for this selection.");const columns=Object.keys(rows[0]);return table(columns.map(c=>c.replaceAll("_"," ")),rows.map(row=>`<tr>${columns.map(c=>`<td>${escapeHTML(["revenue","gross_sales","total_revenue"].includes(c)?money(row[c]):c==="average"?Number(row[c]).toFixed(2):["quantity","reorder_level","count"].includes(c)?number(row[c]):typeof row[c]==="object"?JSON.stringify(row[c]):row[c])}</td>`).join("")}</tr>`));}
function bars(rows,label,value) {if(!rows.length)return empty("No complaint tags match this selection.");const max=Math.max(1,...rows.map(r=>Number(r[value])||0));return rows.map(r=>`<div class="chart-row"><span>${escapeHTML(r[label])}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,Number(r[value])/max*100))}%"></div></div><span>${escapeHTML(r[value])}</span></div>`).join("");}

if(state.token&&state.user) openWorkspace().catch(error=>{signOut();$("#login-error").textContent=error.message;});

function externalFeedbackHTML(result) {
  if(result.status!=="fulfilled")return `<section class="card"><h3>External review benchmark</h3>${errorCard(result.reason)}</section>`;
  const data=result.value;
  return `<section class="card"><div class="card-head"><div><span class="eyebrow teal">EXTERNAL DATA EXPLORER</span><h3 style="margin-top:10px">${escapeHTML(data.source)}</h3><p class="muted">A separate research dataset, with its original sentence sentiment labels.</p></div><span class="pill neutral">${escapeHTML(data.total)} sentences</span></div><div class="tags" style="margin-bottom:18px"><span class="tag">${escapeHTML(data.positive)} positive</span><span class="tag">${escapeHTML(data.negative)} negative</span></div>${data.examples?.length?table(["Source ID","Sentence","Label"],data.examples.map(example=>`<tr><td>${escapeHTML(example.id)}</td><td>${escapeHTML(example.text)}</td><td><span class="pill ${example.sentiment===0?"warning":""}">${example.sentiment===1?"Positive":"Negative"}</span></td></tr>`)):empty("External source sentences have not been imported.")}<p class="hint" style="margin-top:16px">${escapeHTML(data.limitation)} Branch and date filters do not apply to this source dataset.</p><a class="text-button" href="https://archive.ics.uci.edu/dataset/331/sentiment+labelled+sentences" target="_blank" rel="noopener noreferrer">UCI Sentiment Labelled Sentences · source and licence →</a></section>`;
}

// Manager intelligence: current inventory and selected historical sales are labelled separately.
let intelligenceTab="sales";
const insightsTabs={sales:"Sales performance",forecast:"Stock forecast",waste:"Food waste & offers",loyalty:"Customer loyalty",feedback:"Review intelligence"};
const metricHTML=(label,value,note)=>`<div class="metric"><span>${escapeHTML(label)}</span><strong>${escapeHTML(value)}</strong><small>${escapeHTML(note)}</small></div>`;
const percentText=value=>value==null?"No comparison baseline":`${Number(value)>0?"+":""}${number(value)}%`;
function batchesHTML(batches,canDiscard=false) {
  if(!batches?.length)return empty("No stock batches match this selection.");
  return table(["Ingredient / batch","Remaining","Expiry","Status","Value at risk","Action"],batches.map(batch=>`<tr><td><b>${escapeHTML(batch.ingredient_name)}</b><br><small>${batch.id==null?"Legacy stock":`Batch #${escapeHTML(batch.id)}`}</small></td><td>${number(batch.remaining_quantity)} ${escapeHTML(batch.unit)}</td><td>${escapeHTML(batch.expires_on || "Unknown")}${batch.days_to_expiry==null?"":`<br><small>${number(batch.days_to_expiry)} days</small>`}</td><td><span class="pill ${["expired","expiring"].includes(batch.status)?"warning":"neutral"}">${escapeHTML(batch.status==="unknown"?"Expiry unknown — verify":batch.status)}</span></td><td>${batch.value_at_risk==null?(batch.status==="fresh"?"Not at risk":"Unknown"):money(batch.value_at_risk)}</td><td>${canDiscard&&isManager()&&batch.status==="expired"&&batch.id!=null&&Number(batch.remaining_quantity)>0?`<button class="button small danger" data-discard="${escapeHTML(batch.id)}">Discard expired stock</button>`:"—"}</td></tr>`));
}
function wireDiscardBatches() {
  document.querySelectorAll("[data-discard]").forEach(button=>button.addEventListener("click",()=>{
    if(!confirm("Record the disposal of this expired batch? This removes all of its remaining stock and records an audit entry."))return;
    action(button,async()=>{const id=button.dataset.discard;state.discardAttempts[id] ||= key();await send(`/inventory/batches/${encodeURIComponent(id)}/discard`,"POST",{request_key:state.discardAttempts[id]});toast("Expired batch discarded and audited.");await renderView();});
  }));
}
async function renderDashboard(version) {
  const requiresBranch=["forecast","waste"].includes(intelligenceTab);
  if(requiresBranch&&!state.branch)state.branch=state.branches[0]?.id || 1;
  if(!dashboardDates){const today=singaporeToday(),end=new Date(today),start=new Date(today);end.setDate(end.getDate()+1);start.setDate(start.getDate()-30);dashboardDates={start:isoDay(start),end:isoDay(end),as_of:isoDay(today)};}
  dashboardDates.as_of ||= isoDay(singaporeToday());
  const branch=state.branch,salesParams=new URLSearchParams({start:dashboardDates.start,end:dashboardDates.end}),pointParams=new URLSearchParams({as_of:dashboardDates.as_of});
  if(branch){salesParams.set("branch_id",branch);pointParams.set("branch_id",branch);}
  let results;
  if(intelligenceTab==="sales")results=await Promise.allSettled([api(`/analytics/dashboard?${salesParams}`)]);
  else if(intelligenceTab==="forecast")results=await Promise.allSettled([api(`/analytics/forecast?${pointParams}`)]);
  else if(intelligenceTab==="waste")results=await Promise.allSettled([api(`/analytics/waste?${pointParams}`)]);
  else if(intelligenceTab==="loyalty")results=await Promise.allSettled([api(`/analytics/loyalty?${pointParams}`)]);
  else results=await Promise.allSettled([api(`/analytics/feedback?${salesParams}`),api("/analytics/external-feedback")]);
  if(version!==renderVersion)return;
  const data=results[0].status==="fulfilled"?results[0].value:null;
  const panels={sales:salesIntelligenceHTML,forecast:forecastIntelligenceHTML,waste:wasteIntelligenceHTML,loyalty:loyaltyIntelligenceHTML,feedback:feedbackIntelligenceHTML};
  $("#content").innerHTML=`<section class="card filter-card"><form id="dashboard-filters" class="form-row">${branchControl(!requiresBranch)}<label>Sales from<input id="start-date" type="date" value="${escapeHTML(dashboardDates.start)}" required></label><label>Sales until (exclusive)<input id="end-date" type="date" value="${escapeHTML(dashboardDates.end)}" required></label><label>Analysis date<input id="as-of-date" type="date" value="${escapeHTML(dashboardDates.as_of)}" required></label><button class="button primary" type="submit">Update insights</button></form><div class="insight-date-help"><p class="hint">Sales and reviews use the selected date range. Forecast and loyalty use sales before the analysis date; waste uses expiry at that date. Inventory is the current snapshot, never historical reconstructed stock.</p><button id="demo-analysis" class="button secondary small" type="button">Use seeded sales dates</button><button id="compare-analysis" class="button secondary small" type="button">Compare seeded periods</button><button id="today-analysis" class="text-button" type="button">Return to today</button></div></section><nav class="insight-tabs" aria-label="Manager insight categories">${Object.entries(insightsTabs).map(([id,label])=>`<button type="button" data-insight-tab="${id}" class="${id===intelligenceTab?"selected":""}" aria-pressed="${id===intelligenceTab}">${escapeHTML(label)}</button>`).join("")}</nav><div id="insight-panel">${data?panels[intelligenceTab](data,results):`<section class="card"><h3>${escapeHTML(insightsTabs[intelligenceTab])}</h3>${errorCard(results[0].reason)}<button id="retry-insights" type="button" class="button secondary">Retry this view</button></section>`}</div>`;
  $("#dashboard-filters").addEventListener("submit",event=>{event.preventDefault();const start=$("#start-date").value,end=$("#end-date").value,as_of=$("#as-of-date").value;if(start>=end){showError(new Error("The end date must be after the start date."));return;}dashboardDates={start,end,as_of};state.branch=$("#branch-selector").value?Number($("#branch-selector").value):"";renderView();});
  document.querySelectorAll("[data-insight-tab]").forEach(button=>button.addEventListener("click",()=>{intelligenceTab=button.dataset.insightTab;renderView();}));
  $("#demo-analysis").addEventListener("click",()=>{dashboardDates={start:"2026-08-25",end:"2026-09-28",as_of:"2026-09-28"};renderView();});
  $("#compare-analysis").addEventListener("click",()=>{dashboardDates={start:"2026-09-10",end:"2026-09-28",as_of:"2026-09-28"};renderView();});
  $("#today-analysis").addEventListener("click",()=>{dashboardDates=null;renderView();});
  $("#retry-insights")?.addEventListener("click",renderView);
  wireDiscardBatches();
  wireLoyaltyFilter(data);
}
function salesIntelligenceHTML(data) {
  const s=data.summary || {};
  const daily=data.daily || [],hours=data.peak_hours || [],menu=data.menu || [];
  return `<div class="metrics">${metricHTML("Net completed revenue",money(s.net_revenue),"After loyalty discounts")}${metricHTML("Completed orders",number(s.orders),`Average order ${money(s.average_order_value)}`)}${metricHTML("Revenue change",percentText(s.revenue_change_pct),`Previous equal-length period: ${money(s.previous_net_revenue)}`)}</div><div class="equal-columns"><section class="card"><h3>Daily net revenue</h3><p class="muted">Actual completed sales within the selected period.</p>${revenueChartHTML(daily)}</section><section class="card"><h3>Peak ordering hours</h3><p class="muted">Hours and sales date boundaries use the UTC timestamps recorded by this dataset.</p>${hours.length?bars(hours.map(row=>({...row,label:`${String(row.hour).padStart(2,"0")}:00` })),"label","orders"):empty("No completed orders in this period.")}</section></div><section class="card"><h3>Dish performance</h3><p class="muted">Ranked by quantity sold. Dish sales are gross, before order-level points discounts.</p>${menu.length?table(["Rank","Dish","Servings","Gross sales","Previous servings","Quantity change"],menu.map(row=>`<tr><td>${escapeHTML(row.rank)}</td><td><b>${escapeHTML(row.name)}</b></td><td>${number(row.quantity)}</td><td>${money(row.gross_sales)}</td><td>${number(row.previous_quantity)}</td><td>${escapeHTML(percentText(row.quantity_change_pct))}</td></tr>`)):empty("No dish sales in this period.")}</section><div class="equal-columns"><section class="card"><h3>Dishes to review</h3><p class="muted">Sales declined against the preceding equal-length period. Review demand before changing your menu.</p>${data.underperforming?.length?table(["Dish","Current servings","Previous servings","Change"],data.underperforming.map(row=>`<tr><td>${escapeHTML(row.name)}</td><td>${number(row.quantity)}</td><td>${number(row.previous_quantity)}</td><td>${escapeHTML(percentText(row.quantity_change_pct))}</td></tr>`)):empty("No declining dishes with a comparison baseline.")}</section><section class="card"><h3>Branch revenue</h3>${data.branches?.length?table(["Branch","Orders","Net revenue"],data.branches.map(row=>`<tr><td>${escapeHTML(row.name)}</td><td>${number(row.orders)}</td><td>${money(row.net_revenue)}</td></tr>`)):empty("No matching completed orders.")}</section></div>`;
}
function revenueChartHTML(rows) {
  if(!rows.length||!rows.some(row=>Number(row.net_revenue)>0))return empty("No completed revenue in this period. Use seeded sales dates to explore the historical demonstration.");
  const max=Math.max(1,...rows.map(row=>Number(row.net_revenue)||0)),width=600,height=160,pad=8;
  const points=rows.map((row,index)=>`${pad+(index/Math.max(1,rows.length-1))*(width-pad*2)},${height-pad-(Math.max(0,Number(row.net_revenue)||0)/max)*(height-pad*2)}`).join(" ");
  return `<div class="revenue-chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Daily net revenue, maximum ${escapeHTML(money(max))}"><path d="M8 152 H592" stroke="#d7e1dc" fill="none"/><polyline points="${points}" fill="none" stroke="#137a72" stroke-width="3" vector-effect="non-scaling-stroke"/></svg><div class="chart-caption"><span>${escapeHTML(rows[0].date)}</span><span>Peak ${money(max)}</span><span>${escapeHTML(rows.at(-1).date)}</span></div></div><details><summary class="text-button">View accessible daily data</summary>${table(["Date","Orders","Net revenue"],rows.map(row=>`<tr><td>${escapeHTML(row.date)}</td><td>${number(row.orders)}</td><td>${money(row.net_revenue)}</td></tr>`))}</details>`;
}
function forecastIntelligenceHTML(data) {
  const rows=data.ingredients || [],urgent=rows.filter(row=>row.days_remaining!=null&&Number(row.days_remaining)<=2).length;
  return `<div class="metrics">${metricHTML("Forecast history",`${data.history_days || 28} days`,"UTC days before analysis date")}${metricHTML("At most 2 days remaining",number(urgent),"Estimated at average demand")}${metricHTML("Restock target","7 + 2 days","Coverage target plus lead time")}</div><section class="card"><div class="card-head"><div><h3>Ingredient demand & restock forecast</h3><p class="muted">Based on recorded ingredient consumption from completed orders. Includes zero-sales days.</p></div><span class="pill neutral">Estimate</span></div><div class="explanation-box">Days remaining = usable current stock ÷ average daily ingredient usage. Restock = max(0, average daily usage × 9 days − usable stock). A zero-demand history has no exhaustion estimate; it does not mean stock will last forever.</div>${rows.length?table(["Ingredient","Current on hand","Usable stock","Average usage / day","Estimated days left","Suggested restock","Assessment"],rows.map(row=>`<tr><td><b>${escapeHTML(row.name)}</b><br><small>${escapeHTML(row.unit)}</small></td><td>${number(row.quantity)}</td><td>${number(row.usable_quantity)}</td><td>${number(row.average_daily_usage)}</td><td>${row.days_remaining==null?"No demand estimate":number(row.days_remaining)}</td><td>${number(row.recommended_restock)} ${escapeHTML(row.unit)}</td><td><span class="pill ${row.days_remaining!=null&&Number(row.days_remaining)<=2?"warning":"neutral"}">${escapeHTML(row.risk || row.data_status)}</span><br><small>${escapeHTML(row.data_status)}</small></td></tr>`)):empty("No ingredients configured for this branch.")}<p class="hint">Assumes the recent average of historically recorded ingredient consumption continues. Current stock and expiry assessed on ${escapeHTML(data.stock_as_of || isoDay(singaporeToday()))}; recorded demand history ends before ${escapeHTML(data.as_of)} UTC. Selecting a historical date changes demand history, not current usable stock.</p><details><summary class="text-button">Inspect daily usage and 7-day rolling averages</summary>${data.daily?.length?table(["Date","Ingredient","Usage","7-day average"],data.daily.map(row=>`<tr><td>${escapeHTML(row.date)}</td><td>${escapeHTML(rows.find(item=>item.ingredient_id===row.ingredient_id)?.name || row.ingredient_id)}</td><td>${number(row.usage)}</td><td>${number(row.rolling_average)}</td></tr>`)):empty("No usage history.")}</details></section>`;
}
function wasteIntelligenceHTML(data) {
  const s=data.summary || {};
  return `<div class="metrics">${metricHTML("Expiring batches",number(s.expiring_batches),`Within ${data.horizon_days || 7} days of analysis date`)}${metricHTML("Expired batches",number(s.expired_batches),"Excluded from usable portions")}${metricHTML("Known value at risk",money(s.known_value_at_risk),`${number(s.unknown_expiry_batches)} batches have unknown expiry`)}</div><section class="card"><h3>Expiry watchlist</h3><p class="muted">Value is remaining quantity × recorded unit cost. Unknown costs are excluded from the known total.</p>${batchesHTML(data.batches,false)}<p class="hint">Dispose of expired batches from Kitchen stock, where eligibility uses today's date.</p></section><section class="card"><div class="card-head"><div><h3>Explainable promotion suggestions</h3><p class="muted">Dishes that can consume ingredients approaching expiry, ranked by the server's scoring rules.</p></div><span class="pill neutral">Suggestions</span></div><div class="promotion-grid">${data.promotions?.length?data.promotions.map(row=>`<article class="promotion-card"><div class="card-head"><h3>${escapeHTML(row.name)}</h3><span class="pill">Score ${number(row.score)}</span></div><p>${number(row.available_portions)} portions currently available · ${number(row.recent_sales_quantity)} recent servings sold</p><ul>${(row.reasons || []).map(reason=>`<li>${escapeHTML(reason)}</li>`).join("")}</ul><details><summary class="text-button">Why this score?</summary><p class="hint">Score = expiry urgency (up to 50) + relative sales popularity (up to 30) + usable portions (up to 20).</p>${row.score_components?table(["Component","Points"],Object.entries(row.score_components).map(([name,value])=>`<tr><td>${escapeHTML(name.replaceAll("_"," "))}</td><td>${number(value)}</td></tr>`)):""}</details><div class="tags">${(row.ingredients || []).map(item=>`<span class="tag">${escapeHTML(item.name)}: ${number(item.expiring_quantity)} ${escapeHTML(item.unit)} · ${number(item.days_to_expiry)} days</span>`).join("")}</div></article>`).join(""):empty("No eligible dishes using usable ingredients nearing expiry. Receive a dated batch to demonstrate recommendations.")}</div><p class="hint">These recommendations do not publish discounts or change menu prices. The manager chooses an offer after reviewing the reasons. Expired ingredients must never be promoted for sale.</p></section>`;
}
function loyaltyRowsHTML(rows) {
  return rows.length?table(["Customer","Segment","Days since visit","Orders","Net spend","R / F / M"],rows.map(row=>`<tr><td>${escapeHTML(row.name)}</td><td><span class="pill neutral">${escapeHTML(row.segment)}</span></td><td>${row.recency_days==null?"No visits":number(row.recency_days)}</td><td>${number(row.frequency)}</td><td>${money(row.monetary_value)}</td><td>${escapeHTML(row.r_score)} / ${escapeHTML(row.f_score)} / ${escapeHTML(row.m_score)}</td></tr>`)):empty("No customers match this segment.");
}
function loyaltyIntelligenceHTML(data) {
  const rows=data.customers || [],segments=data.segments || [];
  return `<div class="segment-grid">${segments.map(row=>metricHTML(row.segment,number(row.customers),"Customers in this selection")).join("")}</div><section class="card"><h3>Customer loyalty insights</h3><p class="muted">RFM: recency of the last visit, frequency of completed orders, and monetary value of net purchases.</p><div class="explanation-box">Higher R / F / M scores indicate more recent visits, more orders, and higher spend. Branch selection scopes the history; All branches combines visits across branches. Segments use explicit rules rather than a predictive churn model. Recent order frequency and spend use the 90 days before analysis date (UTC). Recency uses the latest recorded visit across earlier history for this branch.</div><label class="segment-control">Customer segment<select id="loyalty-segment"><option value="">All segments</option>${segments.map(row=>`<option value="${escapeHTML(row.segment)}">${escapeHTML(row.segment)}</option>`).join("")}</select></label><div id="loyalty-customers">${loyaltyRowsHTML(rows)}</div><details><summary class="text-button">Inspect scoring thresholds</summary><pre class="scoring-rules">${escapeHTML(JSON.stringify(data.scoring || {},null,2))}</pre></details><p class="hint">Use these insights to plan relevant loyalty offers. Contact preferences are recorded in Customers & feedback; this dashboard sends no messages.</p></section>`;
}
function wireLoyaltyFilter(data) {$("#loyalty-segment")?.addEventListener("change",event=>{$("#loyalty-customers").innerHTML=loyaltyRowsHTML((data.customers || []).filter(row=>!event.target.value || row.segment===event.target.value));});}
function feedbackIntelligenceHTML(data,results) {
  const ratingCount=(data.rating_trends || []).reduce((sum,row)=>sum+Number(row.count || 0),0);
  const averageRating=ratingCount?(data.rating_trends || []).reduce((sum,row)=>sum+Number(row.average || 0)*Number(row.count || 0),0)/ratingCount:null;
  return `<div class="metrics">${metricHTML("Customer reviews",number(data.total_reviews),"Selected branch and sales date range")}${metricHTML("Average rating",averageRating==null?"—":number(averageRating),"On a 1–5 scale")}${metricHTML("Complaint categories",number(data.complaints?.length),"Allowlisted tags on low-rated reviews")}</div><div class="equal-columns"><section class="card"><h3>Frequent complaints</h3>${bars(data.complaints || [],"tag","count")}<p class="hint">A tag is counted once per review. This is keyword and rating-based classification.</p></section><section class="card"><h3>Rating trend</h3>${genericTable(data.rating_trends || [])}</section></div>${externalFeedbackHTML(results[1])}`;
}
